let swiperSales = null;
let swiperHits = null;

function initProductSwipers() {
  const activeWrapper = document.querySelector('.product-swiper__wrapper--active');
  if (!activeWrapper) return;

  const isHits = activeWrapper.classList.contains('product-swiper__wrapper--hit-of-sales');

  // ✅ Уничтожаем ТОЛЬКО тот инстанс, который нужно пересоздать
  if (isHits) {
    if (swiperHits) {
      swiperHits.destroy(true, true);
      swiperHits = null;
    }
  } else {
    if (swiperSales) {
      swiperSales.destroy(true, true);
      swiperSales = null;
    }
  }

  const swiperEl = activeWrapper.querySelector('.swiper');
  if (!swiperEl) return;

  // ✅ Находим элементы scrollbar и pagination ВНУТРИ активного wrapper
  const scrollbarEl = activeWrapper.querySelector('.product-swiper-scrollbar');
  const paginationEl = activeWrapper.querySelector('.product-swiper-pagination');

  // ✅ Полная очистка scrollbar от остатков предыдущего Swiper
  if (scrollbarEl) {
    scrollbarEl.innerHTML = '';
    // Убираем все swiper-* классы, оставляем наши
    const keepClasses = Array.from(scrollbarEl.classList).filter(c => 
      !c.startsWith('swiper-scrollbar-') && 
      c !== 'swiper-scrollbar-horizontal' && 
      c !== 'swiper-scrollbar-vertical'
    );
    scrollbarEl.className = keepClasses.join(' ');
    scrollbarEl.removeAttribute('style');
  }

  // ✅ Полная очистка pagination от остатков предыдущего Swiper
  if (paginationEl) {
    paginationEl.innerHTML = '';
    const keepClasses = Array.from(paginationEl.classList).filter(c => 
      !c.startsWith('swiper-pagination-') && 
      c !== 'swiper-pagination-horizontal' && 
      c !== 'swiper-pagination-vertical' &&
      c !== 'swiper-pagination-progressbar'
    );
    paginationEl.className = keepClasses.join(' ');
    paginationEl.removeAttribute('style');
  }

  // ✅ Также очищаем swiper-wrapper от inline стилей предыдущего инстанса
  const wrapperEl = swiperEl.querySelector('.swiper-wrapper');
  if (wrapperEl) {
    wrapperEl.removeAttribute('style');
  }

  // ✅ Очищаем слайды от swiper-классов
  swiperEl.querySelectorAll('.swiper-slide').forEach(slide => {
    slide.classList.remove(
      'swiper-slide-active', 
      'swiper-slide-next', 
      'swiper-slide-prev',
      'swiper-slide-visible'
    );
    slide.removeAttribute('style');
    slide.removeAttribute('data-swiper-slide-index');
    slide.removeAttribute('role');
    slide.removeAttribute('aria-label');
  });

  // ✅ Очищаем сам контейнер
  swiperEl.classList.remove('swiper-initialized', 'swiper-horizontal', 'swiper-vertical');
  swiperEl.removeAttribute('style');
  // Восстанавливаем width который был
  swiperEl.style.width = '100%';

  const swiperOptions = {
    slidesPerView: 2,
    spaceBetween: 8,
    loop: false,
    autoplay: {
      delay: 5000,
      disableOnInteraction: false,
      pauseOnMouseEnter: true,
    },
    speed: 400,
    grabCursor: true,
    touchRatio: 1,
    touchAngle: 45,
    resistance: true,
    resistanceRatio: 0.85,
    observer: true,           // ✅ Следить за изменениями DOM
    observeParents: true,     // ✅ Следить за родительскими элементами
    navigation: {
      nextEl: '.swiper-button-next__main__product',
      prevEl: '.swiper-button-prev__main__product',
    },
    breakpoints: {
      1320: { slidesPerView: 4, spaceBetween: 12 },
      1050: { slidesPerView: 3, spaceBetween: 10 },
      700: { slidesPerView: 2, spaceBetween: 8 },
    },
  };

  // ✅ Scrollbar — подключаем только если элемент есть
  if (scrollbarEl) {
    swiperOptions.scrollbar = {
      el: scrollbarEl,
      draggable: true,
      hide: false,
      snapOnRelease: false,
      dragSize: 'auto',
    };
  }

  // ✅ Pagination — подключаем только если элемент есть
  if (paginationEl) {
    swiperOptions.pagination = {
      el: paginationEl,
      type: 'progressbar',
    };
  }

  // ✅ Создаём инстанс
  const instance = new Swiper(swiperEl, swiperOptions);

  if (isHits) {
    swiperHits = instance;
  } else {
    swiperSales = instance;
  }

  // ✅ Принудительное обновление после полной инициализации
  requestAnimationFrame(() => {
    // Пересчитать ширину контейнера
    fixSaleProductsSwiper();

    requestAnimationFrame(() => {
      instance.update();
      instance.slideTo(0, 0); // ✅ Сбросить на первый слайд

      if (instance.scrollbar && instance.scrollbar.el) {
        instance.scrollbar.updateSize();
        instance.scrollbar.setTranslate();
      }

      if (instance.pagination && instance.pagination.el) {
        instance.pagination.render();
        instance.pagination.update();
      }

      console.log('✅ Swiper инициализирован:', isHits ? 'Хиты' : 'Распродажа');
      console.log('   slides:', instance.slides.length);
      console.log('   scrollbar el:', !!instance.scrollbar?.el);
      console.log('   pagination el:', !!instance.pagination?.el);

      // ✅ Подключаем draggable pagination ПОСЛЕ полной готовности
      initDraggablePagination();
    });
  });
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initProductSwipers);
} else {
  initProductSwipers();
}

// Переинициализация при смене десктоп/мобилка
let wasMobile = window.matchMedia('(max-width: 800px)').matches;

window.addEventListener('resize', () => {
  const nowMobile = window.matchMedia('(max-width: 800px)').matches;
  if (nowMobile !== wasMobile) {
    wasMobile = nowMobile;
    fixSaleProductsSwiper();
    setTimeout(initProductSwipers, 150);
  }
});


/**
 * Draggable pagination progressbar
 */
function initDraggablePagination() {
  document.querySelectorAll('.product-swiper-pagination').forEach(bar => {
    if (bar._draggableInitialized) {
      if (bar._cleanup) {
        bar._cleanup();
      }
    }

    let isDragging = false;
    let rafId = null;
    let lastClientX = 0;

    function getSwiper() {
      const wrapper = bar.closest('.product-swiper__wrapper');
      if (!wrapper) return null;
      if (wrapper.classList.contains('product-swiper__wrapper--hit-of-sales')) {
        return swiperHits;
      }
      return swiperSales;
    }

    function applyDrag() {
      rafId = null;

      const swiper = getSwiper();
      if (!swiper || !swiper.slides) return;

      const rect = bar.getBoundingClientRect();
      if (rect.width === 0) return;

      const progress = Math.max(0, Math.min(1, (lastClientX - rect.left) / rect.width));

      const maxTranslate = swiper.maxTranslate();
      const minTranslate = swiper.minTranslate();
      const targetTranslate = minTranslate + progress * (maxTranslate - minTranslate);

      // ✅ Только setTranslate — никаких пересчётов классов во время drag
      swiper.setTranslate(targetTranslate);

      // ✅ Обновляем progressbar напрямую
      const progressFill = bar.querySelector('.swiper-pagination-progressbar-fill');
      if (progressFill) {
        progressFill.style.transition = 'none';
        progressFill.style.transform = `scaleX(${progress})`;
      }
    }

    function onStart(e) {
      const swiper = getSwiper();
      if (!swiper) return;

      isDragging = true;
      bar.style.cursor = 'grabbing';
      document.body.style.userSelect = 'none';

      // ✅ Остановить autoplay и убрать transition у wrapper
      if (swiper.autoplay && swiper.autoplay.running) {
        swiper.autoplay.stop();
      }

      const wrapperEl = swiper.wrapperEl;
      if (wrapperEl) {
        wrapperEl.style.transitionDuration = '0ms';
      }

      lastClientX = e.touches ? e.touches[0].clientX : e.clientX;
      applyDrag();

      e.preventDefault();
      e.stopPropagation();
    }

    function onMove(e) {
      if (!isDragging) return;

      lastClientX = e.touches ? e.touches[0].clientX : e.clientX;

      // ✅ Один RAF на кадр — без дублирования
      if (!rafId) {
        rafId = requestAnimationFrame(applyDrag);
      }

      e.preventDefault();
    }

    function onEnd() {
      if (!isDragging) return;
      isDragging = false;
      bar.style.cursor = 'grab';
      document.body.style.userSelect = '';

      if (rafId) {
        cancelAnimationFrame(rafId);
        rafId = null;
      }

      const swiper = getSwiper();
      if (!swiper) return;

      // ✅ Вернуть transition
      const wrapperEl = swiper.wrapperEl;
      if (wrapperEl) {
        wrapperEl.style.transitionDuration = '';
      }

      // ✅ Вернуть transition progressbar
      const progressFill = bar.querySelector('.swiper-pagination-progressbar-fill');
      if (progressFill) {
        progressFill.style.transition = '';
      }

      // ✅ Snap к ближайшему слайду
      swiper.updateActiveIndex();
      swiper.slideTo(swiper.activeIndex, 200);

      if (swiper.autoplay) {
        swiper.autoplay.start();
      }
    }

    const controller = new AbortController();
    const signal = controller.signal;

    bar.addEventListener('mousedown', onStart, { signal });
    document.addEventListener('mousemove', onMove, { signal });
    document.addEventListener('mouseup', onEnd, { signal });

    bar.addEventListener('touchstart', onStart, { passive: false, signal });
    document.addEventListener('touchmove', onMove, { passive: false, signal });
    document.addEventListener('touchend', onEnd, { signal });

    bar.style.cursor = 'grab';

    bar._draggableInitialized = true;
    bar._cleanup = () => {
      controller.abort();
      if (rafId) cancelAnimationFrame(rafId);
      bar._draggableInitialized = false;
    };
  });
}

